beforeExample:
class MyClass {
    void myMethod(String s) {
        if (s.trim().length() == 0) {
            System.out.println("String is empty after trim.");
        }
    }
    void anotherMethod() {
        String myString = "   ";
        if (myString.trim().length() == 0) {
            System.out.println("Whitespace string is empty after trim.");
        }
    }
}

afterExample:
class MyClass {
    void myMethod(String s) {
        if (s.trim().isEmpty()) {
            System.out.println("String is empty after trim.");
        }
    }
    void anotherMethod() {
        String myString = "   ";
        if (myString.trim().isEmpty()) {
            System.out.println("Whitespace string is empty after trim.");
        }
    }
}

